aanschafwaarde in € | 14.065 | 15.805 | 15.595 | 15.865$$, 'inline'),
  ('5e613b61-a6ba-443a-b4ee-0703db7837fc', 'c0a1e956-77c1-47ca-a5b0-d282a41b2f81', $$bron 3: schijventarief inkomstenbelasting box 1 in 2023$$,
